import { useCallback, useEffect, useRef, useState } from 'react';
import { credentialService } from '../services/credential.service';
import { errorMessage } from '../services/trigger.service';

interface Waiting {
  popup: Window;
  state?: string;
  origin?: string;
}

interface GoogleCallback {
  type?: unknown;
  state?: unknown;
  credentialId?: unknown;
  message?: unknown;
}

export function useGoogleOAuthPopup(onConnected: (credentialId: string) => void) {
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const waitingFor = useRef<Waiting | null>(null);
  const watch = useRef<number | null>(null);

  const clearWaiting = useCallback(() => {
    if (watch.current !== null) window.clearInterval(watch.current);
    watch.current = null;
    waitingFor.current = null;
  }, []);

  useEffect(() => {
    const handleMessage = (event: MessageEvent<GoogleCallback>) => {
      const waiting = waitingFor.current;
      if (!waiting?.state || event.source !== waiting.popup ||
          event.origin !== waiting.origin || event.data?.state !== waiting.state) return;
      if (event.data.type === 'oauth-success' && typeof event.data.credentialId === 'string' &&
          event.data.credentialId) {
        clearWaiting();
        setPending(false);
        onConnected(event.data.credentialId);
      } else if (event.data.type === 'oauth-error') {
        clearWaiting();
        setPending(false);
        setError(typeof event.data.message === 'string' ? event.data.message : 'Google sign-in failed');
      }
    };
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, [clearWaiting, onConnected]);

  useEffect(() => () => {
    waitingFor.current?.popup.close();
    clearWaiting();
  }, [clearWaiting]);

  const connect = useCallback(async () => {
    if (waitingFor.current) return;
    setError(null);
    // Open within the click, before awaiting the authorization URL.
    const popup = window.open('', '_blank', 'width=500,height=600');
    if (!popup) {
      setError('Allow pop-ups for this site, then connect Google again.');
      return;
    }
    const waiting: Waiting = { popup };
    waitingFor.current = waiting;
    setPending(true);
    watch.current = window.setInterval(() => {
      if (popup.closed && waitingFor.current === waiting) {
        clearWaiting();
        setPending(false);
        setError('Google sign-in was closed. Connect again to finish.');
      }
    }, 500);
    try {
      const started = await credentialService.googleAuth();
      if (waitingFor.current !== waiting) return;
      waiting.state = started.state;
      waiting.origin = started.callbackOrigin;
      popup.location.href = started.url;
    } catch (cause) {
      if (waitingFor.current !== waiting) return;
      popup.close();
      clearWaiting();
      setPending(false);
      setError(errorMessage(cause, 'Google sign-in could not start'));
    }
  }, [clearWaiting]);

  return { connect, pending, error };
}

