    expect(() => service().getAuthUrl('owner')).toThrow(
      'Google OAuth is not configured',
    );
  });

  it('preserves the reason Google did not provide a usable credential', async () => {
    getToken.mockResolvedValue({ tokens: { access_token: <REDACTED> } });
    const oauth = service();
    const state = new URL(oauth.getAuthUrl('owner')).searchParams.get('state')!;
    await expect(oauth.handleCallback('code-1', state)).rejects.toThrow(
      'No refresh token provided by Google',
    );
    expect(created).toBeUndefined();
  });
});
